+/// Whether gh is logged in to `host` but keeps the token out of `hosts.yml`.
+///
+/// `gh auth login` stores the token in the system keyring (macOS Keychain, Windows Credential
+/// Manager) when one is available, leaving only the user in `hosts.yml`. mise does not run
+/// `gh auth token` on its own, so it finds no token. Callers use this to explain an empty
+/// result; it never runs gh.
+pub fn gh_token_in_keyring(host: &str) -> bool {
+    // Hosts `resolve_token` never looks a token up for: a hint could not change the result.
+    if !Settings::get().github.gh_cli_tokens
+        || is_github_release_asset_host(host)
+        || crate::untrusted_hosts::forge_token_denied(host)
+    {
+        return false;
+    }
+    let Some(hosts) = read_gh_host_entries() else {
+        return false;
+    };
+    // The same hosts `resolve_token` reads, so an alias like `api.github.com` gets the hint too.
+    token_lookup_hosts(host)
+        .into_iter()
+        .filter_map(|lookup_host| hosts.get(lookup_host))
+        .any(GhHostEntry::has_user_without_token)
