+    user: Option<crate::yaml::Value>,
+}
+
+impl GhHostEntry {
+    fn has_user_without_token(&self) -> bool {
+        let has_user = self
+            .user
+            .as_ref()
+            .and_then(crate::yaml::Value::as_str)
+            .is_some_and(|user| !user.trim().is_empty());
+        let has_token = self
+            .oauth_token
+            .as_deref()
+            .is_some_and(|token| !token.trim().is_empty());
+        has_user && !has_token
+    }
 }

