+        let lua = Lua::new();
+        lua.globals()
+            .set("double", async_double(&lua).unwrap())
+            .unwrap();
+        let err = eval(&lua, "return pcall(double, 21)").await.unwrap();
+        // pcall reports the failure instead of raising it.
+        assert_eq!(err.len(), 2);
+        assert_eq!(err[0].as_boolean(), Some(false));
+        assert!(
+            err[1]
