+                let changed = SystemTime::UNIX_EPOCH
+                    + Duration::new(
+                        metadata.ctime().max(0) as u64,
+                        metadata.ctime_nsec().clamp(0, 999_999_999) as u32,
+                    );
+                if changed > since {
+                    return true;
+                }
+            }
+            false
+        })
