+        .iter()
+        .position(|s| s.name == "env")
+        .unwrap();
+    editor.doc.sections[env_idx].expanded = true;
+    editor.cursor.goto(
+        &editor.doc,
+        &CursorTarget::AddButton(AddButtonKind::EnvDotenv(env_idx)),
+    );
+    editor.apply_new_key(file.to_string());
