+    // underline
+    let rendered = err.to_string();
+    if rendered.contains(report.message()) {
+        return tera_err(rendered.replace(report.message(), &hint));
+    }
+    let span = report.span();
+    tera_err(format!(
+        "{hint}\n --> {}:{}:{}",
+        report.filename(),
