+fn base16() -> Theme {
+    let mut theme = Theme::base16();
+    for spec in [
+        &mut theme.title,
+        &mut theme.description,
+        &mut theme.cursor,
+        &mut theme.selected_prefix_fg,
+        &mut theme.selected_option,
+        &mut theme.input_cursor,
