+/// Merge the manifest's ordered `exclude` list. Globs apply in order and the
+/// last match wins, so the list is a program, not a set. When both sides only
+/// appended to the base, their additions commute unless one of them is a
+/// `!glob`, whose meaning depends on what comes before it; the result is the
+/// base, then local's additions, then remote's. Any other divergence (a
+/// removal or reorder on both sides) stays a conflict.
+fn merge_exclusions(
+    base: &[String],
+    local: &[String],
+    remote: &[String],
+    field: &str,
+) -> Result<Vec<String>> {
+    if local == remote || remote == base {
+        return Ok(local.to_vec());
+    }
+    if local == base {
+        return Ok(remote.to_vec());
+    }
+    if local.starts_with(base) && remote.starts_with(base) {
+        let (ours, theirs) = (&local[base.len()..], &remote[base.len()..]);
+        if !ours.iter().chain(theirs).any(|glob| glob.starts_with('!')) {
+            let mut merged = local.to_vec();
+            let ours: std::collections::HashSet<_> = ours.iter().collect();
+            merged.extend(theirs.iter().filter(|glob| !ours.contains(glob)).cloned());
+            return Ok(merged);
+        }
+    }
+    bail!(
+        "enrollment conflict in {field}; both machines changed it in ways that cannot be combined (a removal or a `!glob`). Reconcile it in the repository metadata (`.mise-history/manifest.json`) so no glob is dropped, and keep every local exclusion in place until sync succeeds, so no excluded file is saved"
+    )
+}
+
+/// Merge an enrollment entry's `exclude` or `include` list the way the
+/// manifest's own `exclude` is merged. An absent list states nothing, which
+/// is not an empty one, so unless all three sides state a list the lists are
+/// compared whole.
+fn merge_entry_globs(
+    base: &Option<Vec<String>>,
+    local: &Option<Vec<String>>,
+    remote: &Option<Vec<String>>,
+    field: &str,
+) -> Result<Option<Vec<String>>> {
+    if let (Some(base), Some(local), Some(remote)) = (base, local, remote) {
+        return merge_exclusions(base, local, remote, field).map(Some);
+    }
+    if local == remote || remote == base {
+        Ok(local.clone())
+    } else if local == base {
+        Ok(remote.clone())
+    } else {
+        bail!("enrollment conflict in {field}; reconcile repository metadata before syncing")
+    }
+}
