+pub fn from_json_with_comments_str<T: serde::de::DeserializeOwned>(text: &str) -> Result<T> {
+    if let Some(c) = non_json_whitespace(text) {
+        bail!("invalid whitespace {c:?}: JSON allows only space, tab, CR and LF");
+    }
