+fn graph_install_version<'a>(ba: &BackendArg, name: &'a str) -> Option<&'a str> {
+    let marker = if ba.full_without_opts().starts_with("npm:") {
+        "~aube~"
+    } else if ba.backend_type() == BackendType::Pipx {
+        "~uv~"
+    } else {
+        return None;
+    };
