+            let present = modules
+                .join(dep)
+                .join("package.json")
+                .try_exists()
+                .unwrap_or(false)
+                || package
+                    .join("node_modules")
+                    .join(dep)
+                    .join("package.json")
+                    .try_exists()
+                    .unwrap_or(false);
