+/** Read every HTML page under `root` into path -> { ids, links }. */
+export function readSite(root) {
+  const pages = new Map();
+  const visit = (dir) => {
+    for (const entry of readdirSync(dir, { withFileTypes: true })) {
+      const file = join(dir, entry.name);
+      if (entry.isDirectory()) visit(file);
