+          ids: new Set(
+            [...html.matchAll(/\sid="([^"]+)"/g)].map(([, id]) =>
+              decodeEntities(id),
+            ),
+          ),
+          links: [...html.matchAll(/<a\b[^>]*?\shref="([^"]*)"/g)].map(
+            ([, href]) => decodeEntities(href),
+          ),
+        });
