+    const [fromPath, fromId] = splitHash(from);
+    const page = byPath.get(normalizePath(fromPath));
+    if (!page) {
+      problems.push(
+        `redirects.mjs: ${from} is on a page that does not exist; use pageRedirects`,
+      );
+    } else if (page.ids.has(fromId)) {
