+/// Whether `user` sets a signer option, which retires the registry's.
+fn sets_signer_option(user: &ToolVersionOptions) -> bool {
+    SIGNER_OPTION_KEYS
+        .iter()
+        .any(|key| user.opts.contains_key(*key))
