+    let body = futures_util::stream::unfold(0, |chunk| async move {
+        let bytes = match chunk {
+            0 => b"slow ".as_slice(),
+            1 => b"upload ".as_slice(),
+            2 => b"body".as_slice(),
+            _ => return None,
+        };
+        tokio::time::sleep(Duration::from_millis(80)).await;
+        Some((
+            Ok::<_, std::io::Error>(Bytes::copy_from_slice(bytes)),
+            chunk + 1,
+        ))
+    });
