+        .filter(|pattern| matching_ids(pattern).is_none_or(|ids| !ids.is_empty()))
+        .cloned()
+        .collect::<Vec<_>>();
+    if matched.is_empty() {
+        declared.to_vec()
+    } else {
+        matched
