+monorepo_root = true
+
+[monorepo]
+config_roots = ["apps/*"]
+
+[tasks."env:update"]
+description = "Bump the lockfile"
+alias = "eu"
+run = 'echo updated'
+
+[tasks."env:clear"]
+run = 'echo cleared'
+
+[tasks.precedence]
+alias = ["//apps/web:collision", "pc"]
+run = 'echo precedence'
+EOF
+
+mkdir -p apps/web
+cat <<'EOF' >apps/web/mise.toml
+[tasks.build]
+description = "Build web"
+usage = '''
+flag "--mode <mode>" {
+  choices "dev" "prod"
+}
+'''
+run = 'echo built'
