+    use super::*;
+
+    fn parse(code: &str) -> std::result::Result<MiseInstallSatisfiedResult, LuaError> {
+        let lua = Lua::new();
+        let value = lua.load(code).eval::<Value>()?;
+        MiseInstallSatisfiedResult::from_lua(value, &lua)
+    }
