+        .map(|candidate| format!(" (did you mean '{candidate}'?)"))
+        .unwrap_or_default();
+    Err(eyre::eyre!(
+        "agent '{name}' `process_type` must be one of {}, got '{value}'{suggestion}",
+        PROCESS_TYPES.join(", ")
+    ))
