+/// The sonames `ldd` reported as unresolved, from lines like
+/// `\tlibncurses.so.6 => not found`.
+#[cfg(target_os = "linux")]
+fn parse_ldd_missing(output: &str) -> Vec<String> {
+    output
+        .lines()
+        .filter_map(|line| {
+            let line = line.trim();
+            line.ends_with("=> not found")
+                .then(|| line.split_whitespace().next())
+                .flatten()
+                .map(str::to_string)
+        })
+        .collect()
+}
