+    run_case("resolve-explicit", ["install", "http:resolve-explicit"])
+    run_case("resolve-tty", ["install"], tty=True)
+    run_case("resolve-upgrade", ["upgrade"])
+finally:
+    release.set()
+    server.shutdown()
+    server.server_close()
