+[env]
+Path = "/custom-from-mise"
+EOF
+
+# `Path` survives as itself...
+assert "mise env --json | jq -r '.Path'" "/custom-from-mise"
+
+# ...and PATH is not the thing that was declared.
+assert_not_contains "mise env --json | jq -r '.PATH'" "/custom-from-mise"
