+# implicitly-trust-active-config fast path.
+status=0
+output="$(run_in_pty 'MISE_YES=0 MISE_PARANOID=1 mise env' 2>&1)" || status=$?
+
+if [[ $status == 124 ]]; then
+  fail "mise blocked on a trust prompt that nothing could answer"
+fi
