+        )
+    })?;
+    if !regex!(r"^sha256:[0-9a-f]{64}$").is_match(checksum) {
+        bail!(
+            "Invalid lockfile checksum for precompiled Erlang/OTP {version}; regenerate mise.lock with `mise lock`"
+        );
+    }
+
+    Ok(checksum.to_string())
+}
