+        $script:workdir = Join-Path -Path $env:TEMP -ChildPath "mise-4407-$PID"
+        New-Item -ItemType Directory -Force -Path $script:workdir | Out-Null
+        Push-Location $script:workdir
+
+        mise install usage | Out-Null
+
