+fn python_precompiled_filename_from_url<'a>(url: &'a str, version: &str) -> Option<&'a str> {
+    let (release, filename) = url
+        .strip_prefix(PBS_RELEASE_DOWNLOAD_URL)?
+        .split_once('/')?;
+    if release.len() != 8 || !release.chars().all(|c| c.is_ascii_digit()) {
