+# a lock entry that does not match the prefix is ignored (fresh resolution)
+cat <<EOF >mise.lock
+[[tools.dummy]]
+version = "2.0.0"
+EOF
+rm -rf "$MISE_DATA_DIR/installs/dummy"
+mise install
