+                module example.com/m
+                go 1.22
+                toolchain go1.22.5
+            "#}),
+            "1.22.5"
+        );
+        // `toolchain default` is ignored -> fall back to the `go` directive
+        assert_eq!(
+            parse_gomod(indoc! {r#"
+                go 1.22
+                toolchain default
+            "#}),
+            "1.22"
+        );
