+
+# a structured file value can reference an earlier key from the same file
+cat >mise.toml <<'EOF'
+[env]
+_.file = 'chain.json'
+EOF
+echo '{"BASE": "/opt", "BIN": "${BASE}/bin"}' >chain.json
