+
+[deps.setup]
+auto = true
+run = "touch deps-ran"
+outputs = ["deps-ran"]
+
+[tasks.check]
+tools = { dummy = "1.0.0" }
+run = "touch task-ran"
+EOF
+
+rm -rf "$MISE_DATA_DIR/installs/tiny" "$MISE_DATA_DIR/installs/dummy" "$MISE_DATA_DIR/shims"
+rm -f deps-ran task-ran postinstall-ran mise.lock
+
+output="$(mise run --dry-run check 2>&1)"
+echo "$output"
